package com.eventmanager.controller;
import com.eventmanager.dao.TicketDAO; import com.eventmanager.model.*; import jakarta.servlet.*; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import java.io.IOException;
@WebServlet("/tickets") public class TicketServlet extends HttpServlet { protected void doPost(HttpServletRequest req,HttpServletResponse res)throws ServletException,IOException{User u=(User)req.getSession().getAttribute("user");if(u==null||!"ORGANIZER".equals(u.role)){res.sendError(403);return;}Ticket t=new Ticket();t.eventId=Integer.parseInt(req.getParameter("eventId"));t.ticketName=req.getParameter("ticketName");t.price=Double.parseDouble(req.getParameter("price"));t.quantity=Integer.parseInt(req.getParameter("quantity"));try{new TicketDAO().create(t);res.sendRedirect("dashboard");}catch(Exception e){throw new ServletException(e);}} }
